ROOT=Path(__file__).resolve().parents[2]
DEST=Path(__file__).parent
SYSTEM=next(t['system_prompt'] for t in json.loads((ROOT/'resources/ctl2_test_suite_v4.json').read_text())['tests'] if t['test_id']=='T33')
tests=[]; contexts={}
def f(name,typ='string',nullable=True,**attrs):
    return dict(name=name,type=typ,nullable=str(nullable).lower(),**attrs)
def xml(name,fields):
    return '<Record name="'+name+'" type="delimited" fieldDelimiter="|" recordDelimiter="\\n">\n'+''.join('  <Field '+' '.join(k+'="'+escape(str(v),{'"':'&quot;'})+'"' for k,v in x.items())+'/>\n' for x in fields)+'</Record>'
def base(prefix):
    return [f(prefix+'_ref_no',nullable=False), f('tenant_cd',nullable=False),f('source_file_nm',nullable=False),f('received_at','date',False,format='yyyy-MM-dd HH:mm:ss'),f('source_row_no','long',False),f('owner_team_cd'),f('market_cd'),f('currency_cd',nullable=False),f('batch_ref',nullable=False),f('operator_note'),f('external_trace_id'),f('unused_archive_label')]
def dec(name,nullable=True): return f(name,'decimal',nullable,length='18',scale='2')
def saved_declarations(fields,prefix):
    return '\n'.join(x['type']+' '+prefix+x['name']+';' for x in fields)
def saved_capture(fields,prefix):
    return ''.join(prefix+x['name']+'=$in.0.'+x['name']+';' for x in fields)
def saved_emit(fields,prefix):
    return ''.join('$out.0.'+x['name']+'='+prefix+x['name']+';' for x in fields)
def add(archetype,component,title,intro,clauses,inputs,outputs,code,checks,forbidden,lookup=None,acc=None,context=None):
    tid='T'+str(44+len(tests)); assert 5<=len(clauses)<=10
    msg=title+'\n\n'+intro+'\n\nWrite the complete CTL2 for this component only, including its required entry functions. The connected graph already provides the ordering and resources described below. The receiving application reconciles records by source row and expects these exact business decisions. Treat the following numbered clauses as the acceptance contract; incidental metadata fields remain part of the business record even when no calculation reads them. Do not rely on a different component to perform any of the specified calculations.\n\n'+'\n'.join(f'{i+1}. {c}' for i,c in enumerate(clauses))+'\n\n'
    ins=[xml(n,fs) for n,fs in inputs]; outs=[xml(n,fs) for n,fs in outputs]
    for i,x in enumerate(ins): msg+=f'Input metadata port {i}:\n```xml\n{x}\n```\n\n'
    for i,x in enumerate(outs): msg+=f'Output metadata port {i}:\n```xml\n{x}\n```\n\n'
    if lookup: msg+='Lookup metadata (graph resource, not a port):\n```xml\n'+xml(*lookup)+'\n```\n'
    if acc: msg+='Accumulator metadata:\n```xml\n'+xml(*acc)+'\n```\n'
