# 2: legacy migrations, exactly 30 source fields and 25 target fields.
for entity,old,new,codefield,translations,default in [
 ('policy','legacy_policy_no','policy_number','billing_mode',{'M':'MONTHLY','A':'ANNUAL'},'MANUAL'),
 ('machine','old_machine_id','asset_number','service_class',{'P':'PREVENTIVE','R':'REACTIVE'},'REVIEW'),
 ('dealer','legacy_dealer_key','partner_number','settlement_code',{'D':'DAILY','W':'WEEKLY'},'HOLD')]:
    fs=base(entity)+[f(old,nullable=False),f(codefield),f('display_nm'),f('email_txt'),dec('credit_balance'),f('retired_at','date',format='yyyy-MM-dd')]+[f('migration_'+n) for n in ['segment','region','cost_center','account_mgr','sales_channel','language','tax_ref','phone','fax','old_flag','old_comment','old_batch']]
